#!/usr/bin/env python3.14
# -*- coding: utf-8 -*-
"""Tests for the tables generated by solver.utils.update_doc: the authorization audit table
(gen_authorization_table) — the generated `docs/authorizations.md` view of each
command's module and the rungs that may run it, distinct from the deployed
`authorizations.json` policy — and the tooling reference's make targets and scripts."""
from __future__ import annotations

import tempfile
import unittest.mock
from pathlib import Path

from solver.auth import Authorizations, LADDER, Subject
from solver.config import config
from solver.shell.command import registry
from solver.utils.loader import load_commands
from solver.utils.update_doc import (GENERATORS, MAKEFILE, _least_profile, _module_of,
                                     gen_authorization_table, gen_make_targets, gen_script_table,
                                     make_targets, script_summary, scripts)

_AUTHZ = Authorizations.load()


def _admin_subject() -> Subject:
    return Subject(user='t', slug='t-000000', channel='terminal', auth_method='test',
                   profile='admin')


class AuthorizationTableTests(unittest.TestCase):
    def setUp(self) -> None:
        self._saved_subject = config.subject
        config.subject = _admin_subject()  # admin sees the whole registry
        self.addCleanup(self._restore)
        load_commands()  # populate the registry

    def _restore(self) -> None:
        config.subject = self._saved_subject

    def test_registered_as_a_generator(self) -> None:
        self.assertIs(GENERATORS['authorization-table'], gen_authorization_table)

    def test_table_covers_every_command(self) -> None:
        table = gen_authorization_table()
        for cmd in registry.all():
            self.assertIn(f'`{cmd.name}`', table)  # every command has a row

    def test_table_has_a_column_per_rung(self) -> None:
        table = gen_authorization_table()
        header = table.splitlines()[0]
        for profile in LADDER:
            self.assertIn(profile.capitalize(), header)  # one column per rung
        sample = registry.all()[0]
        self.assertIn(f'`{_module_of(sample)}`', table)  # module column

    def test_each_row_ticks_exactly_the_rungs_at_or_above_the_floor(self) -> None:
        """The tick grid must agree with the floor it is derived from: a run of ticks
        from the command's `requires` rightwards, and nothing below it."""
        rows = {}
        for line in gen_authorization_table().splitlines()[2:]:
            cells = [c.strip() for c in line.strip().strip('|').split('|')]
            rows[cells[1].strip('`')] = cells[2:]
        for cmd in registry.all():
            ticked = [p for p, cell in zip(LADDER, rows[cmd.name]) if cell == '✓']
            expected = [p for p in LADDER if LADDER.index(p) >= LADDER.index(cmd.requires)]
            self.assertEqual(ticked, expected, cmd.name)

    def test_least_profile_is_the_lowest_privilege_that_satisfies(self) -> None:
        # A read-only command is reachable by the base reader; a write-floored one
        # only from contributor up; the admin floor only by admin.
        ls = registry.resolve('ls')
        assert ls is not None
        self.assertEqual(_least_profile(ls), 'reader')
        update_docs = registry.resolve('update-docs')
        assert update_docs is not None
        self.assertEqual(_least_profile(update_docs), 'admin')
        update_tags = registry.resolve('update-tags')
        assert update_tags is not None
        self.assertEqual(_least_profile(update_tags), 'contributor')


class RegistryCompletenessTests(unittest.TestCase):
    """Why `update-docs` is admin-floored: a lesser profile's registry is truncated.

    Registration is profile-filtered, so generating the audit table from a maintainer's
    registry would quietly delete every admin-floored row — from the one document whose
    worth is being complete. This pins the mechanism the floor exists to defend against."""

    def setUp(self) -> None:
        self._saved_subject = config.subject
        self.addCleanup(self._restore)

    def _restore(self) -> None:
        config.subject = self._saved_subject
        load_commands(refresh_modules=True)

    def test_a_maintainers_registry_cannot_see_the_admin_commands(self) -> None:
        config.subject = _admin_subject()
        load_commands(refresh_modules=True)
        admin_floored = {cmd.name for cmd in registry.all() if cmd.requires == 'admin'}
        self.assertIn('users', admin_floored)  # the set is non-empty…
        self.assertIn('key-rekey', admin_floored)  # …and these are in it
        self.assertTrue(admin_floored <= {cmd.name for cmd in registry.all()})


class ToolingReferenceTests(unittest.TestCase):
    """docs/tooling-reference.md is only as complete as its sources: every target and every
    script must say what it does, or the generated line is blank."""

    def test_registered_as_generators(self) -> None:
        self.assertIs(GENERATORS['make-targets'], gen_make_targets)
        self.assertIs(GENERATORS['script-table'], gen_script_table)

    def test_every_make_target_has_a_summary(self) -> None:
        listed = {name for _, targets in make_targets() for name, _ in targets}
        missing = sorted(name for _, targets in make_targets() for name, summary in targets if not summary)
        self.assertEqual(missing, [], 'write a `## ` line above each of these targets')
        phony = MAKEFILE.read_text().split('.PHONY:', 1)[1].split('\n\n', 1)[0]
        declared = set(phony.replace('\\', ' ').split())
        self.assertEqual(declared - listed, set(), 'a .PHONY target outside a `# ── <title> ──` section')

    def test_every_script_has_a_summary(self) -> None:
        missing = [str(path) for path in scripts() if not script_summary(path)]
        self.assertEqual(missing, [], 'give each of these a summary line under the shebang')

    def test_a_shell_summary_is_the_first_header_line(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / 'x.sh'
            path.write_text('#!/usr/bin/env bash\n#\n# Do the thing.\n# More.\nset -e\n')
            self.assertEqual(script_summary(path), 'Do the thing.')
            path.write_text('#!/usr/bin/env bash\nset -e\n# not a header\n')
            self.assertEqual(script_summary(path), '')

    def test_a_pipe_in_a_summary_does_not_split_the_row(self) -> None:
        for line in gen_make_targets().splitlines() + gen_script_table().splitlines():
            if line.startswith('| `') or line.startswith('| ['):
                self.assertEqual(line.replace('\\|', '').count('|'), 3, line)


if __name__ == '__main__':
    unittest.main()
